// Get tasks from Kanboard API response
const response = $input.first().json;
const tasks = response.result || [];

// Filter tasks that need AI enhancement
const tasksNeedingAI = tasks.filter(task => {
  const description = task.description || '';
  const title = task.title || '';
  // Only enhance tasks with no description or very short ones
  return description.trim().length < 20 && title.trim().length > 0;
});

console.log(`Found ${tasks.length} total tasks, ${tasksNeedingAI.length} need AI enhancement`);

// Return each task as a separate item
if (tasksNeedingAI.length === 0) {
  return [];
}

return tasksNeedingAI.map(task => ({ json: task }));

// Get the original task data and AI response
const taskData = $input.first().json;
const aiResponse = $input.last().json.response;

console.log('Original task:', taskData.title);
console.log('AI response:', aiResponse.substring(0, 200));

// Try to parse AI response as JSON
let aiData = null;
try {
  // Look for JSON in the response
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiData = JSON.parse(jsonMatch[0]);
    console.log('Successfully parsed AI JSON:', aiData);
  }
} catch (error) {
  console.log('JSON parsing failed:', error.message);
}

// Create enhanced task data
if (aiData && aiData.description) {
  return {
    json: {
      task_id: taskData.id,
      title: taskData.title,
      description: aiData.description,
      complexity: aiData.complexity || 3,
      tags: Array.isArray(aiData.tags) ? aiData.tags.join(', ') : 'ai-enhanced'
    }
  };
} else {
  // Fallback: create basic enhancement
  return {
    json: {
      task_id: taskData.id,
      title: taskData.title,
      description: `Enhanced task: ${taskData.title}. This task requires attention and proper planning to complete successfully.`,
      complexity: 3,
      tags: 'ai-enhanced, auto-generated, needs-review'
    }
  };
}
